export const css = "\n    :root {\n      /* ---- brand palette (kept var names, refined premium indigo-blue) ---- */\n      --bolt-50: #EEF3FF;\n      --bolt-100: #DEE8FF;\n      --bolt-300: #9FB6FF;\n      --bolt-500: #3D5AFE;\n      --bolt-600: #3247D6;\n      --bolt-700: #2938AD;\n      --bolt-900: #171F63;\n\n      --urgent-50: #FFF6E9;\n      --urgent-400: #FFAE33;\n      --urgent-500: #F59E0B;\n      --urgent-600: #B45309;\n\n      --live-400: #34D399;\n      --live-500: #0EA57D;\n      --live-600: #0C7C61;\n\n      --danger-50: #FEF2F2;\n      --danger-500: #E5484D;\n      --danger-600: #C53030;\n\n      --surface: #F6F7FA;\n      --surface-raised: #FFFFFF;\n      --surface-sunken: #EFF1F5;\n      --ink: #12141C;\n      --ink-soft: #626878;\n      --ink-faint: #9297A6;\n      --line: #E7E9EF;\n      --line-soft: #F0F1F5;\n\n      /* ---- radius scale (buttons 10-12 / cards 12-16 / product 14 / modal 16-18 / section 18-20) ---- */\n      --radius: 1.125rem;\n      --r-xs: 8px;\n      --r-sm: 10px;\n      --r-md: 12px;\n      --r-lg: 14px;\n      --r-xl: 17px;\n      --r-2xl: 20px;\n      --r-full: 999px;\n\n      /* ---- elevation ---- */\n      --shadow-xs: 0 1px 2px rgba(18, 20, 28, .05);\n      --shadow-sm: 0 2px 8px rgba(18, 20, 28, .06);\n      --shadow-md: 0 8px 24px rgba(18, 20, 28, .08);\n      --shadow-lg: 0 16px 40px rgba(18, 20, 28, .12);\n      --shadow-brand: 0 12px 28px -8px rgba(61, 90, 254, .45);\n\n      /* ---- motion ---- */\n      --ease: cubic-bezier(.22, 1, .36, 1);\n      --dur-fast: 150ms;\n      --dur-base: 220ms;\n      --dur-slow: 340ms;\n    }\n\n    * {\n      box-sizing: border-box\n    }\n\n    html {\n      scroll-behavior: smooth\n    }\n\n    body {\n      margin: 0;\n      background: var(--surface);\n      color: var(--ink);\n      font-family: 'Inter', sans-serif;\n      -webkit-font-smoothing: antialiased;\n      -moz-osx-font-smoothing: grayscale\n    }\n\n    h1,\n    h2,\n    h3,\n    h4,\n    .display {\n      font-family: 'Inter', sans-serif;\n      letter-spacing: -0.02em\n    }\n\n    a {\n      color: inherit;\n      text-decoration: none\n    }\n\n    button {\n      font-family: inherit;\n      cursor: pointer\n    }\n\n    button:active {\n      transform: scale(.97)\n    }\n\n    a:focus-visible,\n    button:focus-visible {\n      outline: 2px solid var(--bolt-500);\n      outline-offset: 2px\n    }\n\n    ::selection {\n      background: var(--bolt-300);\n      color: #fff\n    }\n\n    ::-webkit-scrollbar {\n      width: 10px;\n      height: 10px\n    }\n\n    ::-webkit-scrollbar-thumb {\n      background: #D7DAE3;\n      border-radius: 99px;\n      border: 2px solid var(--surface)\n    }\n\n    /* ---------- Motion primitives ---------- */\n    @keyframes fadeIn {\n      from {\n        opacity: 0\n      }\n\n      to {\n        opacity: 1\n      }\n    }\n\n    @keyframes slideUp {\n      from {\n        opacity: 0;\n        transform: translateY(14px)\n      }\n\n      to {\n        opacity: 1;\n        transform: translateY(0)\n      }\n    }\n\n    @keyframes scaleIn {\n      from {\n        opacity: 0;\n        transform: scale(.94)\n      }\n\n      to {\n        opacity: 1;\n        transform: scale(1)\n      }\n    }\n\n    @keyframes floatY {\n\n      0%,\n      100% {\n        transform: translateY(0)\n      }\n\n      50% {\n        transform: translateY(-9px)\n      }\n    }\n\n    @keyframes shimmer {\n      0% {\n        background-position: -300px 0\n      }\n\n      100% {\n        background-position: 300px 0\n      }\n    }\n\n    @keyframes cartBump {\n      0% {\n        transform: scale(1)\n      }\n\n      35% {\n        transform: scale(1.22) rotate(-6deg)\n      }\n\n      65% {\n        transform: scale(.96)\n      }\n\n      100% {\n        transform: scale(1)\n      }\n    }\n\n    @keyframes pulse {\n\n      0%,\n      100% {\n        opacity: 1;\n        transform: scale(1)\n      }\n\n      50% {\n        opacity: .4;\n        transform: scale(.85)\n      }\n    }\n\n    @keyframes pop {\n      from {\n        transform: scale(.95) translateY(6px);\n        opacity: 0\n      }\n\n      to {\n        transform: scale(1) translateY(0);\n        opacity: 1\n      }\n    }\n\n    @keyframes ripple {\n      from {\n        transform: scale(0);\n        opacity: .35\n      }\n\n      to {\n        transform: scale(2.6);\n        opacity: 0\n      }\n    }\n\n    .section,\n    .hero {\n      animation: slideUp var(--dur-slow) var(--ease) both\n    }\n\n    @media (prefers-reduced-motion: reduce) {\n\n      *,\n      *::before,\n      *::after {\n        animation-duration: .001ms !important;\n        animation-iteration-count: 1 !important;\n        transition-duration: .001ms !important;\n        scroll-behavior: auto !important\n      }\n    }\n\n    /* ---------- Navbar ---------- */\n    .nav {\n      position: sticky;\n      top: 0;\n      z-index: 40;\n      background: rgba(255, 255, 255, .78);\n      backdrop-filter: blur(14px) saturate(1.6);\n      -webkit-backdrop-filter: blur(14px) saturate(1.6);\n      border-bottom: 1px solid var(--line);\n      transition: box-shadow var(--dur-base) var(--ease)\n    }\n\n    .nav-inner {\n      max-width: 1240px;\n      margin: 0 auto;\n      padding: 13px 24px;\n      display: flex;\n      align-items: center;\n      gap: 18px\n    }\n\n    .logo {\n      font-weight: 800;\n      font-size: 21px;\n      letter-spacing: -0.03em;\n      color: var(--bolt-600);\n      white-space: nowrap\n    }\n\n    .logo span {\n      color: var(--ink)\n    }\n\n    .search {\n      flex: 1;\n      position: relative;\n      max-width: 540px;\n      display: none\n    }\n\n    .search input {\n      width: 100%;\n      padding: 11px 16px 11px 40px;\n      border-radius: var(--r-md);\n      border: 1.5px solid var(--line);\n      background: var(--surface);\n      font-size: 14px;\n      outline: none;\n      transition: border-color var(--dur-fast) var(--ease), background var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease)\n    }\n\n    .search input:focus {\n      border-color: var(--bolt-500);\n      background: #fff;\n      box-shadow: 0 0 0 4px var(--bolt-50)\n    }\n\n    .search svg {\n      position: absolute;\n      left: 14px;\n      top: 50%;\n      transform: translateY(-50%);\n      color: var(--ink-faint);\n      pointer-events: none\n    }\n\n    @media(min-width:760px) {\n      .search {\n        display: block\n      }\n    }\n\n    .mobile-search-btn {\n      display: flex\n    }\n\n    .icon-btn.mobile-search-btn,\n    .icon-btn.mobile-account-btn {\n      display: flex\n    }\n\n    @media(min-width:760px) {\n\n      .icon-btn.mobile-search-btn,\n      .icon-btn.mobile-account-btn {\n        display: none\n      }\n    }\n\n    .mobile-account-btn .avatar-dot {\n      width: 22px;\n      height: 22px;\n      border-radius: var(--r-full);\n      background: var(--bolt-500);\n      color: #fff;\n      font-size: 12px;\n      font-weight: 700;\n      display: none;\n      align-items: center;\n      justify-content: center\n    }\n\n    .mobile-account-btn.logged-in svg {\n      display: none\n    }\n\n    .mobile-account-btn.logged-in .avatar-dot {\n      display: flex\n    }\n\n    .mobile-search-row {\n      display: none;\n      align-items: center;\n      gap: 10px;\n      padding: 10px 24px 16px;\n      max-width: 1240px;\n      margin: 0 auto;\n      color: var(--ink-faint);\n      animation: slideUp var(--dur-base) var(--ease) both\n    }\n\n    .mobile-search-row.open {\n      display: flex\n    }\n\n    .mobile-search-row input {\n      flex: 1;\n      padding: 11px 14px;\n      border-radius: var(--r-md);\n      border: 1.5px solid var(--line);\n      background: var(--surface);\n      font-size: 14px;\n      outline: none;\n      color: var(--ink);\n      font-family: inherit\n    }\n\n    .mobile-search-row input:focus {\n      border-color: var(--bolt-500);\n      background: #fff\n    }\n\n    @media(min-width:760px) {\n      .mobile-search-row {\n        display: none !important\n      }\n    }\n\n    .nav-actions {\n      margin-left: auto;\n      display: flex;\n      align-items: center;\n      gap: 6px\n    }\n\n    .icon-btn {\n      position: relative;\n      border: none;\n      background: none;\n      padding: 9px;\n      border-radius: var(--r-full);\n      color: var(--ink-soft);\n      display: flex;\n      transition: background var(--dur-fast) var(--ease), color var(--dur-fast) var(--ease), transform var(--dur-fast) var(--ease)\n    }\n\n    .icon-btn:hover {\n      background: var(--surface-sunken);\n      transform: translateY(-1px)\n    }\n\n    .icon-btn.bump {\n      animation: cartBump .45s var(--ease)\n    }\n\n    .badge {\n      position: absolute;\n      top: 0;\n      right: 0;\n      min-width: 16px;\n      height: 16px;\n      padding: 0 3px;\n      border-radius: var(--r-full);\n      background: var(--urgent-500);\n      color: #fff;\n      font-size: 10px;\n      font-weight: 700;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      box-shadow: 0 0 0 2px #fff\n    }\n\n    .signin-btn {\n      display: none;\n      align-items: center;\n      gap: 6px;\n      border: 1.5px solid var(--line);\n      padding: 9px 18px;\n      border-radius: var(--r-md);\n      font-size: 14px;\n      font-weight: 600;\n      color: var(--ink);\n      background: none;\n      transition: border-color var(--dur-fast) var(--ease), background var(--dur-fast) var(--ease)\n    }\n\n    .signin-btn:hover {\n      background: var(--surface);\n      border-color: var(--line)\n    }\n\n    @media(min-width:760px) {\n      .signin-btn {\n        display: flex\n      }\n    }\n\n    .user-btn {\n      display: none;\n      align-items: center;\n      gap: 8px;\n      border: none;\n      background: none;\n      padding: 5px 12px 5px 5px;\n      border-radius: var(--r-full);\n      font-size: 14px;\n      font-weight: 500;\n      color: var(--ink)\n    }\n\n    .user-btn:hover {\n      background: var(--surface)\n    }\n\n    @media(min-width:760px) {\n      .user-btn.show {\n        display: flex\n      }\n    }\n\n    .avatar {\n      width: 28px;\n      height: 28px;\n      border-radius: var(--r-full);\n      background: linear-gradient(135deg, var(--bolt-500), var(--bolt-700));\n      color: #fff;\n      font-size: 12px;\n      font-weight: 700;\n      display: flex;\n      align-items: center;\n      justify-content: center\n    }\n\n    .menu-wrap {\n      position: relative\n    }\n\n    .menu {\n      position: absolute;\n      right: 0;\n      top: calc(100% + 10px);\n      width: 208px;\n      background: #fff;\n      border: 1px solid var(--line);\n      border-radius: var(--r-lg);\n      box-shadow: var(--shadow-lg);\n      overflow: hidden;\n      opacity: 0;\n      transform: translateY(-6px) scale(.98);\n      pointer-events: none;\n      transition: opacity var(--dur-base) var(--ease), transform var(--dur-base) var(--ease);\n      transform-origin: top right\n    }\n\n    .menu.open {\n      opacity: 1;\n      transform: translateY(0) scale(1);\n      pointer-events: auto\n    }\n\n    .menu-head {\n      padding: 13px 15px;\n      border-bottom: 1px solid var(--line-soft)\n    }\n\n    .menu-head .name {\n      font-weight: 700;\n      font-size: 14px\n    }\n\n    .menu-head .email {\n      font-size: 12px;\n      color: var(--ink-soft)\n    }\n\n    .menu-item {\n      display: flex;\n      align-items: center;\n      gap: 9px;\n      width: 100%;\n      padding: 11px 15px;\n      font-size: 14px;\n      background: none;\n      border: none;\n      text-align: left;\n      color: var(--ink);\n      transition: background var(--dur-fast)\n    }\n\n    .menu-item:hover {\n      background: var(--surface)\n    }\n\n    .menu-item.danger {\n      color: var(--danger-500)\n    }\n\n    /* ---------- Promo banner (was: hero) ---------- */\n    .promo-banner {\n      --promo-bg-a: #EEF4EA;\n      --promo-bg-b: #FBFAF5;\n      --promo-fresh: var(--live-500);\n      max-width: 1240px;\n      margin: 28px auto 0;\n      padding: 0 24px\n    }\n\n    .promo-banner-inner {\n      position: relative;\n      overflow: hidden;\n      border-radius: 18px;\n      border: 1px solid var(--line);\n      background: linear-gradient(115deg, var(--promo-bg-a) 0%, var(--promo-bg-b) 46%, #fff 100%);\n      padding: 40px 28px;\n      display: flex;\n      flex-direction: column;\n      gap: 32px;\n      animation: slideUp var(--dur-slow) var(--ease) both\n    }\n\n    @media(min-width:900px) {\n      .promo-banner {\n        margin-top: 40px\n      }\n\n      .promo-banner-inner {\n        flex-direction: row;\n        align-items: center;\n        justify-content: space-between;\n        padding: 56px 64px;\n        gap: 24px;\n        min-height: 360px\n      }\n    }\n\n    /* soft decorative blobs, purely atmospheric */\n    .promo-banner-inner::before,\n    .promo-banner-inner::after {\n      content: \"\";\n      position: absolute;\n      border-radius: 50%;\n      filter: blur(46px);\n      pointer-events: none;\n      opacity: .55\n    }\n\n    .promo-banner-inner::before {\n      width: 260px;\n      height: 260px;\n      background: var(--bolt-100);\n      top: -110px;\n      right: 8%\n    }\n\n    .promo-banner-inner::after {\n      width: 200px;\n      height: 200px;\n      background: #DCEEDB;\n      bottom: -90px;\n      left: 4%\n    }\n\n    .promo-copy {\n      position: relative;\n      max-width: 480px;\n      z-index: 1\n    }\n\n    .promo-eyebrow {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      background: #fff;\n      border: 1px solid var(--line);\n      color: var(--ink-soft);\n      font-size: 11.5px;\n      font-weight: 700;\n      letter-spacing: .09em;\n      text-transform: uppercase;\n      padding: 7px 12px;\n      border-radius: 9px;\n      box-shadow: var(--shadow-xs);\n      margin-bottom: 18px;\n      animation: slideUp var(--dur-slow) var(--ease) both\n    }\n\n    .promo-title {\n      font-family: 'Fraunces', 'Inter', serif;\n      font-size: 32px;\n      line-height: 1.12;\n      letter-spacing: -0.01em;\n      font-weight: 600;\n      color: var(--ink);\n      margin: 0 0 12px;\n      animation: slideUp var(--dur-slow) var(--ease) both;\n      animation-delay: 40ms\n    }\n\n    @media(min-width:640px) {\n      .promo-title {\n        font-size: 40px\n      }\n    }\n\n    @media(min-width:900px) {\n      .promo-title {\n        font-size: 46px\n      }\n    }\n\n    .promo-title em {\n      font-style: italic;\n      color: var(--bolt-600)\n    }\n\n    .promo-subtitle {\n      font-size: 16px;\n      line-height: 1.6;\n      color: var(--ink-soft);\n      max-width: 400px;\n      margin: 0 0 22px;\n      animation: slideUp var(--dur-slow) var(--ease) both;\n      animation-delay: 80ms\n    }\n\n    .promo-actions {\n      display: flex;\n      align-items: center;\n      flex-wrap: wrap;\n      gap: 18px;\n      animation: slideUp var(--dur-slow) var(--ease) both;\n      animation-delay: 120ms\n    }\n\n    .promo-discount {\n      display: inline-flex;\n      align-items: baseline;\n      gap: 6px;\n      background: var(--bolt-50);\n      border: 1px solid var(--bolt-100);\n      color: var(--bolt-600);\n      font-weight: 800;\n      font-size: 15px;\n      padding: 9px 14px;\n      border-radius: 10px\n    }\n\n    .promo-discount span {\n      font-weight: 500;\n      font-size: 11.5px;\n      color: var(--bolt-600);\n      opacity: .8\n    }\n\n    .promo-link {\n      display: inline-flex;\n      align-items: center;\n      gap: 5px;\n      background: none;\n      border: none;\n      padding: 0;\n      color: var(--ink);\n      font-weight: 600;\n      font-size: 14.5px;\n      border-bottom: 1.5px solid var(--line);\n      padding-bottom: 2px;\n      transition: border-color var(--dur-fast) var(--ease), color var(--dur-fast) var(--ease), gap var(--dur-fast) var(--ease)\n    }\n\n    .promo-link:hover {\n      color: var(--bolt-600);\n      border-color: var(--bolt-300);\n      gap: 8px\n    }\n\n    /* ---- promo product imagery cluster ---- */\n    .promo-media {\n      position: relative;\n      z-index: 1;\n      width: 100%;\n      max-width: 340px;\n      height: 210px;\n      margin: 0 auto;\n      flex: none\n    }\n\n    @media(min-width:900px) {\n      .promo-media {\n        margin: 0;\n        width: 340px\n      }\n    }\n\n    .promo-photo {\n      position: absolute;\n      border-radius: 16px;\n      overflow: hidden;\n      box-shadow: var(--shadow-lg);\n      border: 4px solid #fff;\n      animation: scaleIn var(--dur-slow) var(--ease) both\n    }\n\n    .promo-photo img {\n      display: block;\n      width: 100%;\n      height: 100%;\n      object-fit: cover\n    }\n\n    .promo-photo-a {\n      width: 168px;\n      height: 168px;\n      top: 4px;\n      left: 8px;\n      transform: rotate(-6deg);\n      animation-delay: 100ms;\n      z-index: 2\n    }\n\n    .promo-photo-b {\n      width: 132px;\n      height: 132px;\n      top: 30px;\n      right: 4px;\n      transform: rotate(7deg);\n      animation-delay: 180ms;\n      z-index: 1;\n      animation-name: scaleIn, floatY;\n      animation-duration: var(--dur-slow), 4.5s;\n      animation-timing-function: var(--ease), ease-in-out;\n      animation-iteration-count: 1, infinite;\n      animation-delay: 180ms, 700ms\n    }\n\n    .promo-photo-c {\n      width: 108px;\n      height: 108px;\n      bottom: 2px;\n      left: 78px;\n      transform: rotate(-4deg);\n      animation-delay: 260ms;\n      z-index: 3\n    }\n\n    .promo-photo:hover img {\n      transform: scale(1.06)\n    }\n\n    .promo-photo img {\n      transition: transform var(--dur-base) var(--ease)\n    }\n\n    @media(max-width:520px) {\n      .promo-media {\n        height: 190px;\n        max-width: 280px\n      }\n\n      .promo-photo-a {\n        width: 140px;\n        height: 140px\n      }\n\n      .promo-photo-b {\n        width: 108px;\n        height: 108px;\n        right: -6px\n      }\n\n      .promo-photo-c {\n        width: 92px;\n        height: 92px;\n        left: 62px\n      }\n    }\n\n    /* ---------- Footer ---------- */\n    footer {\n      margin-top: 48px;\n      padding: 0;\n      background: var(--surface-raised);\n      border-top: 1px solid var(--line);\n      color: var(--ink-soft);\n      font-size: 13px\n    }\n\n    .footer-inner {\n      max-width: 1240px;\n      margin: 0 auto;\n      padding: 34px 24px;\n      display: flex;\n      flex-wrap: wrap;\n      align-items: center;\n      justify-content: space-between;\n      gap: 20px\n    }\n\n    .footer-brand .logo {\n      font-weight: 800;\n      font-size: 19px;\n      letter-spacing: -0.02em;\n      color: var(--bolt-600);\n      margin-bottom: 6px\n    }\n\n    .footer-brand p {\n      font-size: 13px;\n      line-height: 1.5;\n      color: var(--ink-soft);\n      margin: 0\n    }\n\n    .footer-links {\n      display: flex;\n      align-items: center;\n      gap: 28px;\n      flex-wrap: wrap\n    }\n\n    .footer-links a,\n    .footer-links button {\n      font: inherit;\n      font-size: 13.5px;\n      color: var(--ink-soft);\n      background: none;\n      border: none;\n      padding: 0;\n      cursor: pointer;\n      transition: color var(--dur-fast)\n    }\n\n    .footer-links a:hover,\n    .footer-links button:hover {\n      color: var(--bolt-600)\n    }\n\n    .footer-copy {\n      font-size: 13px;\n      color: var(--ink-faint);\n      white-space: nowrap\n    }\n\n    @media(max-width:760px) {\n      .footer-inner {\n        flex-direction: column;\n        align-items: flex-start;\n        text-align: left\n      }\n\n      .footer-links {\n        gap: 18px\n      }\n    }\n\n    /* ---------- Section ---------- */\n    .section {\n      max-width: 1240px;\n      margin: 0 auto;\n      padding: 34px 24px\n    }\n\n    .section-head {\n      display: flex;\n      align-items: baseline;\n      justify-content: space-between;\n      margin-bottom: 20px\n    }\n\n    .section-head h2 {\n      font-size: 21px;\n      margin: 0;\n      font-weight: 800\n    }\n\n    .section-head a {\n      font-size: 13px;\n      font-weight: 600;\n      color: var(--bolt-600);\n      transition: opacity var(--dur-fast)\n    }\n\n    .section-head a:hover {\n      opacity: .7\n    }\n\n    .flash-countdown {\n      display: inline-flex;\n      align-items: center;\n      gap: 3px;\n      font-size: 12.5px;\n      font-weight: 600;\n      color: var(--urgent-600);\n      background: var(--urgent-50);\n      padding: 6px 12px;\n      border-radius: var(--r-full);\n      font-variant-numeric: tabular-nums\n    }\n\n    .flash-countdown b {\n      font-weight: 700\n    }\n\n    @media(max-width:520px) {\n      .flash-countdown {\n        display: none\n      }\n    }\n\n    .categories {\n      display: flex;\n      gap: 10px;\n      overflow-x: auto;\n      padding-bottom: 6px;\n      margin-bottom: 10px;\n      scrollbar-width: none\n    }\n\n    .categories::-webkit-scrollbar {\n      display: none\n    }\n\n    .cat-pill {\n      flex: none;\n      padding: 9px 16px;\n      border-radius: var(--r-md);\n      border: 1.5px solid var(--line);\n      font-size: 13px;\n      font-weight: 600;\n      background: #fff;\n      white-space: nowrap;\n      color: var(--ink-soft);\n      transition: background var(--dur-fast) var(--ease), border-color var(--dur-fast) var(--ease), color var(--dur-fast) var(--ease), transform var(--dur-fast) var(--ease)\n    }\n\n    .cat-pill:hover {\n      border-color: var(--bolt-300);\n      color: var(--ink);\n      transform: translateY(-1px)\n    }\n\n    .cat-pill.active {\n      background: var(--bolt-500);\n      border-color: var(--bolt-500);\n      color: #fff;\n      box-shadow: 0 6px 16px -6px rgba(61, 90, 254, .55)\n    }\n\n    .grid {\n      display: grid;\n      grid-template-columns: repeat(2, 1fr);\n      gap: 16px\n    }\n\n    @media(min-width:640px) {\n      .grid {\n        grid-template-columns: repeat(3, 1fr)\n      }\n    }\n\n    @media(min-width:960px) {\n      .grid {\n        grid-template-columns: repeat(4, 1fr)\n      }\n    }\n\n    .card {\n      background: #fff;\n      border: 1px solid var(--line);\n      border-radius: var(--r-lg);\n      overflow: hidden;\n      display: flex;\n      flex-direction: column;\n      transition: transform var(--dur-base) var(--ease), box-shadow var(--dur-base) var(--ease), border-color var(--dur-base) var(--ease);\n      animation: slideUp var(--dur-slow) var(--ease) both\n    }\n\n    .card:hover {\n      border-color: transparent;\n      box-shadow: var(--shadow-md);\n      transform: translateY(-4px)\n    }\n\n    .card-img {\n      aspect-ratio: 1;\n      background: var(--surface);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 40px;\n      position: relative;\n      overflow: hidden\n    }\n\n    .card-img img {\n      width: 100%;\n      height: 100%;\n      object-fit: cover;\n      display: block;\n      transition: transform var(--dur-slow) var(--ease)\n    }\n\n    .card:hover .card-img img {\n      transform: scale(1.06)\n    }\n\n    .flash-tag {\n      position: absolute;\n      top: 9px;\n      left: 9px;\n      background: linear-gradient(135deg, var(--urgent-400), var(--urgent-600));\n      color: #fff;\n      font-size: 10px;\n      font-weight: 700;\n      letter-spacing: .04em;\n      padding: 4px 9px 4px 7px;\n      border-radius: var(--r-full);\n      display: flex;\n      align-items: center;\n      gap: 4px;\n      box-shadow: 0 3px 8px rgba(180, 83, 9, .35)\n    }\n\n    .flash-tag svg {\n      flex-shrink: 0\n    }\n\n    .card-body {\n      padding: 13px 14px 14px;\n      display: flex;\n      flex-direction: column;\n      gap: 6px;\n      flex: 1\n    }\n\n    .card-body .title {\n      font-size: 13.5px;\n      font-weight: 600;\n      line-height: 1.3;\n      min-height: 34px\n    }\n\n    .card-body .meta {\n      font-size: 11.5px;\n      color: var(--ink-soft);\n      display: flex;\n      align-items: center;\n      gap: 4px\n    }\n\n    .card-body .price-row {\n      display: flex;\n      align-items: baseline;\n      gap: 6px;\n      margin-top: 2px\n    }\n\n    .price {\n      font-family: 'Inter', sans-serif;\n      font-weight: 800;\n      font-size: 16px;\n      letter-spacing: -0.01em\n    }\n\n    .price-old {\n      font-size: 12px;\n      color: var(--ink-faint);\n      text-decoration: line-through\n    }\n\n    .add-btn {\n      margin-top: auto;\n      border: none;\n      background: var(--bolt-500);\n      color: #fff;\n      font-weight: 600;\n      font-size: 13px;\n      padding: 9px;\n      border-radius: var(--r-sm);\n      transition: background var(--dur-fast) var(--ease), transform var(--dur-fast) var(--ease);\n      box-shadow: 0 4px 10px -3px rgba(61, 90, 254, .45);\n      position: relative;\n      overflow: hidden\n    }\n\n    .add-btn:hover {\n      background: var(--bolt-600);\n      transform: translateY(-1px)\n    }\n\n    .add-btn:active {\n      transform: translateY(0) scale(.96)\n    }\n\n    .wish-btn {\n      position: absolute;\n      top: 9px;\n      right: 9px;\n      width: 30px;\n      height: 30px;\n      border-radius: var(--r-full);\n      border: none;\n      background: rgba(255, 255, 255, .92);\n      backdrop-filter: blur(4px);\n      color: #64748B;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      box-shadow: 0 2px 6px rgba(0, 0, 0, .12);\n      transition: color var(--dur-fast) var(--ease), transform var(--dur-fast) var(--ease);\n      z-index: 2\n    }\n\n    .wish-btn:hover {\n      color: var(--danger-500);\n      transform: scale(1.08)\n    }\n\n    .wish-btn.active {\n      color: var(--danger-500)\n    }\n\n    .wish-btn.active svg {\n      fill: currentColor\n    }\n\n    /* ---------- Cart drawer ---------- */\n    .overlay {\n      position: fixed;\n      inset: 0;\n      background: rgba(15, 18, 28, .45);\n      backdrop-filter: blur(2px);\n      opacity: 0;\n      pointer-events: none;\n      transition: opacity var(--dur-base) var(--ease);\n      z-index: 60\n    }\n\n    .overlay.show {\n      opacity: 1;\n      pointer-events: auto\n    }\n\n    .drawer {\n      position: fixed;\n      top: 0;\n      right: 0;\n      height: 100%;\n      width: 100%;\n      max-width: 400px;\n      background: #fff;\n      z-index: 61;\n      transform: translateX(100%);\n      transition: transform var(--dur-slow) var(--ease);\n      display: flex;\n      flex-direction: column;\n      box-shadow: -16px 0 48px rgba(0, 0, 0, .18)\n    }\n\n    .drawer.show {\n      transform: translateX(0)\n    }\n\n    .drawer-head {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      padding: 18px 22px;\n      border-bottom: 1px solid var(--line)\n    }\n\n    .drawer-head h3 {\n      margin: 0;\n      font-size: 17px;\n      font-weight: 700\n    }\n\n    .close-x {\n      border: none;\n      background: none;\n      padding: 7px;\n      border-radius: var(--r-full);\n      color: #64748B;\n      transition: background var(--dur-fast)\n    }\n\n    .close-x:hover {\n      background: var(--surface)\n    }\n\n    .drawer-body {\n      flex: 1;\n      overflow-y: auto;\n      padding: 12px 22px\n    }\n\n    .cart-line {\n      display: flex;\n      gap: 12px;\n      padding: 13px 0;\n      border-bottom: 1px solid var(--line-soft);\n      animation: fadeIn var(--dur-base) var(--ease) both\n    }\n\n    .cart-thumb {\n      width: 56px;\n      height: 56px;\n      border-radius: var(--r-sm);\n      background: var(--surface);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 22px;\n      flex: none;\n      overflow: hidden\n    }\n\n    .cart-thumb img {\n      width: 100%;\n      height: 100%;\n      object-fit: cover;\n      display: block\n    }\n\n    .cart-info {\n      flex: 1;\n      min-width: 0\n    }\n\n    .cart-info .t {\n      font-size: 13px;\n      font-weight: 600;\n      margin-bottom: 2px\n    }\n\n    .cart-info .p {\n      font-size: 13px;\n      color: var(--ink-soft)\n    }\n\n    .qty {\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      margin-top: 7px\n    }\n\n    .qty button {\n      width: 23px;\n      height: 23px;\n      border-radius: var(--r-xs);\n      border: 1px solid var(--line);\n      background: #fff;\n      font-size: 13px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      transition: background var(--dur-fast), border-color var(--dur-fast)\n    }\n\n    .qty button:hover {\n      background: var(--surface);\n      border-color: var(--bolt-300)\n    }\n\n    .qty span {\n      font-size: 13px;\n      font-weight: 700;\n      min-width: 14px;\n      text-align: center\n    }\n\n    .drawer-foot {\n      padding: 16px 22px;\n      border-top: 1px solid var(--line)\n    }\n\n    .subtotal-row {\n      display: flex;\n      justify-content: space-between;\n      font-size: 14px;\n      margin-bottom: 12px;\n      color: var(--ink-soft)\n    }\n\n    .subtotal-row b {\n      font-family: 'Inter', sans-serif;\n      font-size: 17px;\n      color: var(--ink)\n    }\n\n    .delivery-note {\n      font-size: 12.5px;\n      font-weight: 600;\n      padding: 10px 12px;\n      border-radius: var(--r-sm);\n      margin-bottom: 14px;\n      display: flex;\n      align-items: center;\n      gap: 6px\n    }\n\n    .delivery-note.pending {\n      background: var(--bolt-50);\n      color: var(--bolt-700)\n    }\n\n    .delivery-note.unlocked {\n      background: #E9FBF3;\n      color: var(--live-600)\n    }\n\n    .coupon-input-row {\n      display: flex;\n      gap: 8px;\n      margin-bottom: 6px\n    }\n\n    .coupon-input-row input {\n      flex: 1;\n      min-width: 0;\n      padding: 10px 12px;\n      border-radius: var(--r-sm);\n      border: 1.5px solid var(--line);\n      font-size: 13px;\n      text-transform: uppercase;\n      outline: none;\n      transition: border-color var(--dur-fast)\n    }\n\n    .coupon-input-row input:focus {\n      border-color: var(--bolt-500)\n    }\n\n    .coupon-input-row input::placeholder {\n      text-transform: none\n    }\n\n    .coupon-input-row button {\n      padding: 10px 15px;\n      border-radius: var(--r-sm);\n      border: 1.5px solid var(--line);\n      background: #fff;\n      font-size: 13px;\n      font-weight: 700;\n      white-space: nowrap;\n      transition: background var(--dur-fast), border-color var(--dur-fast)\n    }\n\n    .coupon-input-row button:hover {\n      border-color: var(--bolt-500);\n      color: var(--bolt-600)\n    }\n\n    .coupon-error {\n      font-size: 12px;\n      color: var(--danger-500);\n      min-height: 14px;\n      margin-bottom: 8px\n    }\n\n    .coupon-avail {\n      display: flex;\n      flex-direction: column;\n      gap: 6px;\n      margin-bottom: 14px\n    }\n\n    .coupon-chip {\n      display: flex;\n      flex-direction: column;\n      align-items: flex-start;\n      gap: 1px;\n      text-align: left;\n      padding: 9px 12px;\n      border-radius: var(--r-sm);\n      border: 1px dashed var(--bolt-300);\n      background: var(--bolt-50)\n    }\n\n    .coupon-chip .code {\n      font-size: 12.5px;\n      font-weight: 700;\n      color: var(--bolt-700)\n    }\n\n    .coupon-chip .desc {\n      font-size: 11.5px;\n      color: var(--ink-soft)\n    }\n\n    .coupon-chip.disabled {\n      opacity: .55;\n      background: var(--surface);\n      border-color: var(--line)\n    }\n\n    .coupon-chip.disabled .code {\n      color: var(--ink-soft)\n    }\n\n    .coupon-applied {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 8px;\n      background: #E9FBF3;\n      color: var(--live-600);\n      font-size: 12.5px;\n      font-weight: 700;\n      padding: 10px 12px;\n      border-radius: var(--r-sm);\n      margin-bottom: 14px\n    }\n\n    .coupon-applied button {\n      background: none;\n      border: none;\n      color: inherit;\n      font-weight: 700;\n      cursor: pointer;\n      font-size: 14px;\n      line-height: 1\n    }\n\n    .coupon-save-box {\n      padding-bottom: 16px;\n      margin-bottom: 16px;\n      border-bottom: 1px dashed var(--line)\n    }\n\n    .coupon-save-box .coupon-input-row {\n      margin-bottom: 6px\n    }\n\n    .coupon-save-hint {\n      font-size: 11.5px;\n      color: var(--ink-soft);\n      margin: -2px 0 2px\n    }\n\n    .pm-add-row {\n      display: flex;\n      gap: 8px;\n      margin-bottom: 16px\n    }\n\n    .pm-add-row button {\n      flex: 1\n    }\n\n    .pm-icon {\n      font-size: 15px\n    }\n\n    .delivery-bar {\n      height: 5px;\n      border-radius: var(--r-full);\n      background: rgba(0, 0, 0, .07);\n      margin-top: 6px;\n      overflow: hidden\n    }\n\n    .delivery-bar span {\n      display: block;\n      height: 100%;\n      background: currentColor;\n      border-radius: var(--r-full);\n      transition: width var(--dur-slow) var(--ease)\n    }\n\n    .empty-cart {\n      text-align: center;\n      padding: 64px 20px;\n      color: var(--ink-soft);\n      animation: fadeIn var(--dur-slow) var(--ease) both\n    }\n\n    .empty-cart .e {\n      font-size: 36px;\n      margin-bottom: 12px\n    }\n\n    /* ---------- Modal (login) ---------- */\n    .modal-overlay {\n      position: fixed;\n      inset: 0;\n      background: rgba(12, 14, 22, .55);\n      backdrop-filter: blur(3px);\n      z-index: 78;\n      display: none;\n      align-items: center;\n      justify-content: center;\n      padding: 20px\n    }\n\n    .modal-overlay.show {\n      display: flex;\n      animation: fadeIn var(--dur-base) var(--ease) both\n    }\n\n    textarea.addr-input {\n      width: 100%;\n      padding: 11px 12px;\n      border-radius: var(--r-sm);\n      border: 1.5px solid var(--line);\n      font-size: 14px;\n      outline: none;\n      background: #fff;\n      resize: none;\n      font-family: inherit;\n      transition: border-color var(--dur-fast)\n    }\n\n    textarea.addr-input:focus {\n      border-color: var(--bolt-500)\n    }\n\n    .track-summary {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      background: var(--surface);\n      border-radius: var(--r-lg);\n      padding: 15px 17px;\n      margin-bottom: 20px\n    }\n\n    .track-summary .n {\n      font-family: 'Inter', sans-serif;\n      font-weight: 800;\n      font-size: 20px\n    }\n\n    .track-summary .lbl {\n      font-size: 11.5px;\n      color: var(--ink-soft)\n    }\n\n    .track-road {\n      position: relative;\n      height: 4px;\n      background: var(--line);\n      border-radius: var(--r-full);\n      margin: 36px 6px 8px\n    }\n\n    .track-fill {\n      position: absolute;\n      left: 0;\n      top: 0;\n      height: 100%;\n      background: var(--bolt-500);\n      border-radius: var(--r-full);\n      width: 0%;\n      transition: width 1s var(--ease)\n    }\n\n    .track-rider {\n      position: absolute;\n      top: 50%;\n      left: 0%;\n      transform: translate(-50%, -50%) scaleX(-1);\n      font-size: 22px;\n      transition: left 1s var(--ease)\n    }\n\n    .track-stages {\n      display: flex;\n      justify-content: space-between\n    }\n\n    .track-stage {\n      flex: 1;\n      text-align: center;\n      font-size: 11px;\n      color: var(--ink-faint);\n      font-weight: 600;\n      position: relative\n    }\n\n    .track-stage .dot {\n      width: 10px;\n      height: 10px;\n      border-radius: var(--r-full);\n      background: var(--line);\n      margin: 0 auto 6px;\n      transition: background var(--dur-base), box-shadow var(--dur-base)\n    }\n\n    .track-stage.done .dot {\n      background: var(--live-500)\n    }\n\n    .track-stage.done {\n      color: var(--live-600)\n    }\n\n    .track-stage.active {\n      color: var(--bolt-600)\n    }\n\n    .track-stage.active .dot {\n      background: var(--bolt-500);\n      box-shadow: 0 0 0 4px var(--bolt-100)\n    }\n\n    .track-eta {\n      text-align: center;\n      margin: 22px 0 18px\n    }\n\n    .track-eta b {\n      font-family: 'Inter', sans-serif;\n      font-size: 24px;\n      display: block;\n      font-weight: 800\n    }\n\n    .track-eta span {\n      font-size: 12px;\n      color: var(--ink-soft)\n    }\n\n    .track-addr {\n      background: var(--surface);\n      border-radius: var(--r-md);\n      padding: 13px 14px;\n      font-size: 13px;\n      color: #475569;\n      margin-bottom: 18px\n    }\n\n    .track-addr b {\n      display: block;\n      font-size: 12.5px;\n      color: var(--ink);\n      margin-bottom: 2px\n    }\n\n    .track-pay-badge {\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      font-size: 12px;\n      font-weight: 700;\n      padding: 6px 12px;\n      border-radius: var(--r-full);\n      margin-bottom: 14px\n    }\n\n    .track-pay-badge.paid {\n      background: #E9FBF3;\n      color: var(--live-600)\n    }\n\n    .track-pay-badge.due {\n      background: #FFF3E9;\n      color: #C2410C\n    }\n\n    .order-pay-badge {\n      font-size: 11px;\n      font-weight: 700;\n      padding: 2px 8px;\n      border-radius: var(--r-full);\n      white-space: nowrap\n    }\n\n    .order-pay-badge.paid {\n      background: #E9FBF3;\n      color: var(--live-600)\n    }\n\n    .order-pay-badge.due {\n      background: #FFF3E9;\n      color: #C2410C\n    }\n\n    .modal {\n      background: #fff;\n      border-radius: var(--r-2xl);\n      width: 100%;\n      max-width: 380px;\n      padding: 30px;\n      position: relative;\n      animation: pop var(--dur-base) var(--ease);\n      box-shadow: var(--shadow-lg)\n    }\n\n    .modal-close {\n      position: absolute;\n      top: 16px;\n      right: 16px;\n      border: none;\n      background: none;\n      color: var(--ink-faint);\n      padding: 7px;\n      border-radius: var(--r-full);\n      transition: background var(--dur-fast)\n    }\n\n    .modal-close:hover {\n      background: var(--surface)\n    }\n\n    .modal .brand {\n      text-align: center;\n      font-weight: 800;\n      font-size: 20px;\n      color: var(--bolt-600);\n      margin-bottom: 18px\n    }\n\n    .modal .brand span {\n      color: var(--ink)\n    }\n\n    .modal h2 {\n      font-size: 21px;\n      margin: 0 0 4px;\n      font-weight: 800\n    }\n\n    .modal .sub {\n      font-size: 13.5px;\n      color: var(--ink-soft);\n      margin-bottom: 20px\n    }\n\n    .modal .sub button {\n      background: none;\n      border: none;\n      color: var(--bolt-600);\n      font-weight: 700;\n      font-size: 13.5px;\n      padding: 0\n    }\n\n    .field {\n      position: relative;\n      margin-bottom: 10px\n    }\n\n    .field svg {\n      position: absolute;\n      left: 13px;\n      top: 50%;\n      transform: translateY(-50%);\n      color: var(--ink-faint)\n    }\n\n    .field input {\n      width: 100%;\n      padding: 12px 12px 12px 38px;\n      border-radius: var(--r-sm);\n      border: 1.5px solid var(--line);\n      font-size: 14px;\n      outline: none;\n      background: #fff;\n      transition: border-color var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease)\n    }\n\n    .field input:focus {\n      border-color: var(--bolt-500);\n      box-shadow: 0 0 0 4px var(--bolt-50)\n    }\n\n    .form-error {\n      background: var(--urgent-50);\n      color: var(--urgent-600);\n      font-size: 12.5px;\n      padding: 9px 11px;\n      border-radius: var(--r-xs);\n      margin-bottom: 10px\n    }\n\n    .submit-btn {\n      width: 100%;\n      background: var(--bolt-500);\n      color: #fff;\n      border: none;\n      padding: 13px;\n      border-radius: var(--r-md);\n      font-weight: 700;\n      font-size: 14.5px;\n      margin-top: 4px;\n      transition: background var(--dur-fast) var(--ease), transform var(--dur-fast) var(--ease);\n      box-shadow: var(--shadow-brand)\n    }\n\n    .submit-btn:hover {\n      background: var(--bolt-600);\n      transform: translateY(-1px)\n    }\n\n    .divider {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      font-size: 11.5px;\n      color: var(--ink-faint);\n      margin: 18px 0\n    }\n\n    .divider .ln {\n      flex: 1;\n      height: 1px;\n      background: var(--line)\n    }\n\n    .oauth-row {\n      display: flex;\n      gap: 8px\n    }\n\n    .oauth-btn {\n      flex: 1;\n      border: 1.5px solid var(--line);\n      background: #fff;\n      padding: 10px;\n      border-radius: var(--r-md);\n      font-size: 13px;\n      font-weight: 600;\n      transition: background var(--dur-fast)\n    }\n\n    .oauth-btn:hover {\n      background: var(--surface)\n    }\n\n    .fine {\n      text-align: center;\n      font-size: 11.5px;\n      color: var(--ink-faint);\n      margin-top: 16px\n    }\n\n    /* ---------- Toast ---------- */\n    .toast {\n      position: fixed;\n      bottom: 24px;\n      left: 50%;\n      transform: translateX(-50%) translateY(24px) scale(.96);\n      background: var(--ink);\n      color: #fff;\n      padding: 13px 22px;\n      border-radius: var(--r-full);\n      font-size: 13.5px;\n      font-weight: 500;\n      opacity: 0;\n      pointer-events: none;\n      transition: opacity var(--dur-base) var(--ease), transform var(--dur-base) var(--ease);\n      z-index: 80;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      box-shadow: var(--shadow-lg)\n    }\n\n    .toast.show {\n      opacity: 1;\n      transform: translateX(-50%) translateY(0) scale(1)\n    }\n\n    footer {\n      border-top: 1px solid var(--line);\n      margin-top: 44px;\n      padding: 40px 24px;\n      text-align: center;\n      color: var(--ink-soft);\n      font-size: 13px\n    }\n\n    /* ---------- global dark mode ---------- */\n    body.dark-mode {\n      --surface: #0E0F13;\n      --surface-raised: #191A20;\n      --surface-sunken: #202127;\n      --ink: #F1F5F9;\n      --ink-soft: #98A2B3;\n      --ink-faint: #6B7280;\n      --line: #2B2D35;\n      --line-soft: #24252C\n    }\n\n    body.dark-mode .card,\n    body.dark-mode .nav,\n    body.dark-mode .modal,\n    body.dark-mode .drawer,\n    body.dark-mode .cat-pill {\n      background: var(--surface-raised);\n      border-color: var(--line)\n    }\n\n    body.dark-mode .search input,\n    body.dark-mode .field input,\n    body.dark-mode textarea.addr-input {\n      background: var(--surface);\n      border-color: var(--line);\n      color: var(--ink)\n    }\n\n    body.dark-mode .nav {\n      background: rgba(14, 15, 19, .82)\n    }\n\n    body.dark-mode .card-img {\n      background: #101115\n    }\n\n    /* ---------- Profile screen ---------- */\n    .profile-overlay {\n      position: fixed;\n      inset: 0;\n      background: #fff;\n      color: var(--ink);\n      z-index: 75;\n      transform: translateX(100%);\n      transition: transform var(--dur-slow) var(--ease);\n      overflow-y: auto\n    }\n\n    .profile-overlay.show {\n      transform: translateX(0)\n    }\n\n    .profile-head {\n      display: flex;\n      align-items: center;\n      gap: 14px;\n      padding: 16px 20px;\n      position: sticky;\n      top: 0;\n      background: rgba(255, 255, 255, .85);\n      backdrop-filter: blur(10px);\n      border-bottom: 1px solid var(--line);\n      z-index: 2\n    }\n\n    .profile-back {\n      width: 38px;\n      height: 38px;\n      border-radius: var(--r-full);\n      border: 1.5px solid var(--line);\n      background: none;\n      color: var(--ink);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      flex: none;\n      transition: background var(--dur-fast)\n    }\n\n    .profile-back:hover {\n      background: var(--surface)\n    }\n\n    .profile-head h2 {\n      margin: 0;\n      font-size: 18px;\n      font-weight: 700\n    }\n\n    .profile-hero {\n      text-align: center;\n      padding: 26px 20px 26px\n    }\n\n    .profile-hero .avatar-lg {\n      width: 78px;\n      height: 78px;\n      border-radius: var(--r-full);\n      margin: 0 auto 14px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 30px;\n      font-weight: 700;\n      color: #fff;\n      background: linear-gradient(135deg, var(--bolt-500), var(--bolt-700));\n      box-shadow: var(--shadow-brand)\n    }\n\n    .profile-hero h3 {\n      margin: 0 0 4px;\n      font-size: 20px;\n      font-weight: 800\n    }\n\n    .profile-hero p {\n      margin: 0;\n      color: var(--ink-soft);\n      font-size: 13.5px\n    }\n\n    .quick-actions {\n      display: grid;\n      grid-template-columns: repeat(3, 1fr);\n      gap: 10px;\n      padding: 0 20px 22px\n    }\n\n    .qa-card {\n      background: var(--surface);\n      border: 1px solid var(--line);\n      border-radius: var(--r-lg);\n      padding: 17px 8px;\n      text-align: center;\n      color: var(--ink);\n      transition: background var(--dur-fast), border-color var(--dur-fast), transform var(--dur-fast)\n    }\n\n    .qa-card:hover {\n      background: var(--bolt-50);\n      border-color: var(--bolt-300);\n      transform: translateY(-2px)\n    }\n\n    .qa-card svg {\n      margin-bottom: 8px;\n      color: var(--ink-soft)\n    }\n\n    .qa-card span {\n      display: block;\n      font-size: 12px;\n      font-weight: 600\n    }\n\n    .profile-toggle {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 12px;\n      background: var(--surface);\n      border: 1px solid var(--line);\n      border-radius: var(--r-lg);\n      padding: 14px 16px;\n      margin: 0 20px 10px\n    }\n\n    .profile-toggle .t {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      font-size: 14px;\n      font-weight: 600\n    }\n\n    .profile-toggle .sub {\n      font-size: 11.5px;\n      color: var(--ink-soft);\n      font-weight: 400;\n      margin-top: 3px;\n      max-width: 280px\n    }\n\n    .switch {\n      position: relative;\n      width: 42px;\n      height: 24px;\n      border-radius: var(--r-full);\n      background: #CBD5E1;\n      border: none;\n      flex: none;\n      cursor: pointer;\n      transition: background var(--dur-base)\n    }\n\n    .switch.on {\n      background: var(--live-500)\n    }\n\n    .switch .knob {\n      position: absolute;\n      top: 2px;\n      left: 2px;\n      width: 20px;\n      height: 20px;\n      border-radius: var(--r-full);\n      background: #fff;\n      transition: left var(--dur-base) var(--ease);\n      box-shadow: 0 1px 3px rgba(0, 0, 0, .25)\n    }\n\n    .switch.on .knob {\n      left: 20px\n    }\n\n    .plist {\n      margin: 18px 20px 0;\n      border-radius: var(--r-lg);\n      overflow: hidden;\n      background: var(--surface);\n      border: 1px solid var(--line)\n    }\n\n    .plist-head {\n      padding: 14px 16px 4px;\n      font-weight: 700;\n      font-size: 15px\n    }\n\n    .plist-row {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      width: 100%;\n      padding: 14px 16px;\n      border: none;\n      background: none;\n      color: var(--ink);\n      font-size: 14.5px;\n      font-weight: 500;\n      text-align: left;\n      border-top: 1px solid var(--line);\n      transition: background var(--dur-fast)\n    }\n\n    .plist-row:first-of-type {\n      border-top: none\n    }\n\n    .plist-row:hover {\n      background: var(--surface-sunken)\n    }\n\n    .plist-row svg {\n      flex: none;\n      color: var(--ink-soft)\n    }\n\n    .plist-row .chev {\n      margin-left: auto;\n      color: var(--ink-faint)\n    }\n\n    .plist-row.danger {\n      color: var(--danger-500)\n    }\n\n    .profile-version {\n      text-align: center;\n      color: var(--ink-faint);\n      font-size: 12px;\n      padding: 26px 20px 40px\n    }\n\n    /* ---------- Orders screen ---------- */\n    .orders-overlay {\n      position: fixed;\n      inset: 0;\n      background: #fff;\n      color: var(--ink);\n      z-index: 76;\n      transform: translateX(100%);\n      transition: transform var(--dur-slow) var(--ease);\n      overflow-y: auto\n    }\n\n    .orders-overlay.show {\n      transform: translateX(0)\n    }\n\n    .orders-list {\n      padding: 6px 20px 30px\n    }\n\n    .order-card {\n      background: var(--surface);\n      border: 1px solid var(--line);\n      border-radius: var(--r-xl);\n      padding: 17px;\n      margin-bottom: 14px;\n      transition: box-shadow var(--dur-fast)\n    }\n\n    .order-card:hover {\n      box-shadow: var(--shadow-sm)\n    }\n\n    .order-card-top {\n      display: flex;\n      justify-content: space-between;\n      align-items: flex-start;\n      margin-bottom: 10px\n    }\n\n    .order-card-top .oid {\n      font-weight: 700;\n      font-size: 14.5px\n    }\n\n    .order-card-top .odate {\n      font-size: 11.5px;\n      color: var(--ink-soft);\n      margin-top: 2px\n    }\n\n    .order-status {\n      font-size: 11px;\n      font-weight: 700;\n      padding: 4px 10px;\n      border-radius: var(--r-full)\n    }\n\n    .order-status.delivered {\n      background: #E9FBF3;\n      color: var(--live-600)\n    }\n\n    .order-status.transit {\n      background: #FFF3D6;\n      color: #B45309\n    }\n\n    .order-items {\n      font-size: 13px;\n      color: var(--ink-soft);\n      line-height: 1.6;\n      margin-bottom: 10px\n    }\n\n    .order-card-foot {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding-top: 10px;\n      border-top: 1px solid var(--line);\n      font-size: 13px\n    }\n\n    .order-card-foot b {\n      font-family: 'Inter', sans-serif;\n      font-size: 15px\n    }\n\n    .orders-empty {\n      text-align: center;\n      padding: 74px 30px;\n      color: var(--ink-soft)\n    }\n\n    .orders-empty .e {\n      font-size: 40px;\n      margin-bottom: 14px\n    }\n\n    .orders-empty button {\n      margin-top: 16px\n    }\n\n    .addr-actions {\n      display: flex;\n      gap: 6px\n    }\n\n    .addr-actions button {\n      width: 30px;\n      height: 30px;\n      border-radius: var(--r-xs);\n      border: 1px solid var(--line);\n      background: #fff;\n      color: var(--ink-soft);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      transition: background var(--dur-fast), color var(--dur-fast), border-color var(--dur-fast)\n    }\n\n    .addr-actions button:hover {\n      background: var(--surface)\n    }\n\n    .addr-actions button.del:hover {\n      color: var(--danger-500);\n      border-color: var(--danger-500)\n    }\n\n    .addr-default {\n      display: inline-block;\n      font-size: 10px;\n      font-weight: 700;\n      color: var(--live-600);\n      background: #E9FBF3;\n      padding: 2px 8px;\n      border-radius: var(--r-full);\n      margin-left: 8px\n    }\n\n    /* ---------- Info pages (About / Return Policy / Disclaimer) ---------- */\n    .info-overlay {\n      position: fixed;\n      inset: 0;\n      background: #fff;\n      color: var(--ink);\n      z-index: 76;\n      transform: translateX(100%);\n      transition: transform var(--dur-slow) var(--ease);\n      overflow-y: auto\n    }\n\n    .info-overlay.show {\n      transform: translateX(0)\n    }\n\n    .info-body {\n      max-width: 760px;\n      margin: 0 auto;\n      padding: 40px 24px 64px;\n      animation: slideUp var(--dur-slow) var(--ease) both\n    }\n\n    .info-eyebrow {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      font-size: 11.5px;\n      font-weight: 700;\n      letter-spacing: .08em;\n      text-transform: uppercase;\n      color: var(--bolt-600);\n      background: var(--bolt-50);\n      border: 1px solid var(--bolt-100);\n      padding: 6px 12px;\n      border-radius: 9px;\n      margin-bottom: 16px\n    }\n\n    .info-body h1 {\n      font-size: 30px;\n      font-weight: 800;\n      letter-spacing: -0.02em;\n      margin: 0 0 12px;\n      line-height: 1.15\n    }\n\n    @media(min-width:640px) {\n      .info-body h1 {\n        font-size: 36px\n      }\n    }\n\n    .info-lead {\n      font-size: 16px;\n      line-height: 1.65;\n      color: var(--ink-soft);\n      max-width: 620px;\n      margin: 0 0 8px\n    }\n\n    .info-updated {\n      font-size: 12.5px;\n      color: var(--ink-faint);\n      margin: 0 0 32px\n    }\n\n    .info-section {\n      padding: 28px 0;\n      border-top: 1px solid var(--line)\n    }\n\n    .info-section:first-of-type {\n      border-top: none;\n      padding-top: 8px\n    }\n\n    .info-section h2 {\n      font-size: 19px;\n      font-weight: 700;\n      margin: 0 0 10px;\n      letter-spacing: -0.01em\n    }\n\n    .info-section p {\n      font-size: 14.5px;\n      line-height: 1.7;\n      color: var(--ink-soft);\n      margin: 0 0 12px\n    }\n\n    .info-section ul {\n      margin: 0 0 12px;\n      padding-left: 20px;\n      display: flex;\n      flex-direction: column;\n      gap: 8px\n    }\n\n    .info-section li {\n      font-size: 14.5px;\n      line-height: 1.6;\n      color: var(--ink-soft)\n    }\n\n    .info-grid {\n      display: grid;\n      grid-template-columns: 1fr;\n      gap: 12px;\n      margin-top: 6px\n    }\n\n    @media(min-width:640px) {\n      .info-grid {\n        grid-template-columns: 1fr 1fr\n      }\n    }\n\n    .info-card {\n      background: var(--surface);\n      border: 1px solid var(--line);\n      border-radius: 14px;\n      padding: 18px\n    }\n\n    .info-card b {\n      display: block;\n      font-size: 14.5px;\n      font-weight: 700;\n      color: var(--ink);\n      margin-bottom: 4px\n    }\n\n    .info-card span {\n      font-size: 13px;\n      line-height: 1.55;\n      color: var(--ink-soft)\n    }\n\n    .info-callout {\n      display: flex;\n      gap: 12px;\n      background: var(--bolt-50);\n      border: 1px solid var(--bolt-100);\n      border-radius: 14px;\n      padding: 16px 18px;\n      margin: 6px 0 12px\n    }\n\n    .info-callout svg {\n      flex: none;\n      color: var(--bolt-600);\n      margin-top: 1px\n    }\n\n    .info-callout p {\n      margin: 0;\n      color: var(--ink);\n      font-size: 13.5px;\n      line-height: 1.6\n    }\n\n    .info-callout.warn {\n      background: #FFF7E8;\n      border-color: #F5E3B8\n    }\n\n    .info-callout.warn svg {\n      color: #B8860B\n    }\n\n    .info-steps {\n      counter-reset: infostep;\n      display: flex;\n      flex-direction: column;\n      gap: 14px;\n      margin: 6px 0 12px\n    }\n\n    .info-step {\n      display: flex;\n      gap: 14px\n    }\n\n    .info-step .num {\n      counter-increment: infostep;\n      flex: none;\n      width: 26px;\n      height: 26px;\n      border-radius: var(--r-full);\n      background: var(--bolt-500);\n      color: #fff;\n      font-size: 12.5px;\n      font-weight: 700;\n      display: flex;\n      align-items: center;\n      justify-content: center\n    }\n\n    .info-step .num::before {\n      content: counter(infostep)\n    }\n\n    .info-step-body b {\n      display: block;\n      font-size: 14.5px;\n      font-weight: 700;\n      margin-bottom: 2px\n    }\n\n    .info-step-body span {\n      font-size: 13.5px;\n      color: var(--ink-soft);\n      line-height: 1.55\n    }\n\n    .info-cta {\n      display: flex;\n      align-items: center;\n      gap: 14px;\n      flex-wrap: wrap;\n      margin-top: 8px;\n      padding-top: 28px;\n      border-top: 1px solid var(--line)\n    }\n\n    .info-cta p {\n      margin: 0;\n      font-size: 13.5px;\n      color: var(--ink-faint)\n    }\n\n    @media(max-width:640px) {\n      .info-body {\n        padding: 28px 18px 48px\n      }\n    }\n\n    /* ---------- Wallet ---------- */\n    .wallet-balance-card {\n      margin: 6px 20px 20px;\n      padding: 24px 20px;\n      border-radius: var(--r-xl);\n      background: linear-gradient(150deg, var(--bolt-500), var(--bolt-700) 85%);\n      color: #fff;\n      text-align: center;\n      box-shadow: var(--shadow-brand);\n      position: relative;\n      overflow: hidden\n    }\n\n    .wallet-balance-card::after {\n      content: \"\";\n      position: absolute;\n      width: 180px;\n      height: 180px;\n      border-radius: 50%;\n      background: rgba(255, 255, 255, .08);\n      right: -60px;\n      top: -70px\n    }\n\n    .wallet-balance-card .lbl {\n      font-size: 12.5px;\n      opacity: .85;\n      margin-bottom: 4px;\n      position: relative\n    }\n\n    .wallet-balance-card .amt {\n      font-family: 'Inter', sans-serif;\n      font-size: 35px;\n      font-weight: 800;\n      margin-bottom: 18px;\n      position: relative\n    }\n\n    .wallet-balance-card .btn-primary {\n      background: #fff;\n      color: var(--bolt-700);\n      box-shadow: none;\n      position: relative\n    }\n\n    .wallet-balance-card .btn-primary:hover {\n      background: #EEF3FF\n    }\n\n    .wallet-tx {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 10px;\n      background: var(--surface);\n      border: 1px solid var(--line);\n      border-radius: var(--r-md);\n      padding: 12px 14px;\n      margin-bottom: 10px\n    }\n\n    .wallet-tx .icon {\n      width: 34px;\n      height: 34px;\n      border-radius: var(--r-full);\n      background: #E9FBF3;\n      color: var(--live-600);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      flex: none\n    }\n\n    .wallet-tx .mid {\n      flex: 1;\n      min-width: 0\n    }\n\n    .wallet-tx .mid .t {\n      font-size: 13.5px;\n      font-weight: 600\n    }\n\n    .wallet-tx .mid .d {\n      font-size: 11.5px;\n      color: var(--ink-soft)\n    }\n\n    .wallet-tx .amt {\n      font-family: 'Inter', sans-serif;\n      font-size: 14.5px;\n      font-weight: 700;\n      color: var(--live-600)\n    }\n\n    .wallet-tx.debit .icon {\n      background: var(--danger-50);\n      color: var(--danger-600)\n    }\n\n    .wallet-tx.debit .amt {\n      color: var(--danger-600)\n    }\n\n    /* payment method picker (checkout) */\n    .pay-method-list {\n      display: flex;\n      flex-direction: column;\n      gap: 8px;\n      margin-bottom: 10px\n    }\n\n    .pay-method-option {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      padding: 12px;\n      border-radius: var(--r-md);\n      border: 1.5px solid var(--line);\n      background: #fff;\n      cursor: pointer;\n      text-align: left;\n      width: 100%;\n      transition: border-color var(--dur-fast), background var(--dur-fast)\n    }\n\n    .pay-method-option.selected {\n      border-color: var(--bolt-500);\n      background: var(--bolt-50)\n    }\n\n    .pay-method-option.disabled {\n      opacity: .5;\n      cursor: not-allowed\n    }\n\n    .pay-method-option .pm-radio {\n      width: 16px;\n      height: 16px;\n      border-radius: 50%;\n      border: 2px solid var(--line);\n      flex-shrink: 0;\n      position: relative\n    }\n\n    .pay-method-option.selected .pm-radio {\n      border-color: var(--bolt-500)\n    }\n\n    .pay-method-option.selected .pm-radio::after {\n      content: \"\";\n      position: absolute;\n      inset: 3px;\n      border-radius: 50%;\n      background: var(--bolt-500)\n    }\n\n    .pay-method-option .pm-emoji {\n      font-size: 18px;\n      flex: none\n    }\n\n    .pay-method-option .pm-body {\n      flex: 1;\n      min-width: 0\n    }\n\n    .pay-method-option .pm-title {\n      font-size: 13.5px;\n      font-weight: 600;\n      color: var(--ink);\n      display: block\n    }\n\n    .pay-method-option .pm-sub {\n      font-size: 11.5px;\n      color: var(--ink-soft);\n      display: block;\n      margin-top: 1px\n    }\n\n    .upi-chip-row {\n      display: flex;\n      gap: 8px;\n      margin-bottom: 14px;\n      flex-wrap: wrap\n    }\n\n    .upi-chip {\n      padding: 9px 16px;\n      border-radius: var(--r-md);\n      border: 1.5px solid var(--line);\n      background: #fff;\n      font-size: 13.5px;\n      font-weight: 600;\n      color: var(--ink);\n      transition: border-color var(--dur-fast), background var(--dur-fast), color var(--dur-fast)\n    }\n\n    .upi-chip:hover {\n      border-color: var(--bolt-500)\n    }\n\n    .upi-chip.active {\n      background: var(--bolt-500);\n      border-color: var(--bolt-500);\n      color: #fff\n    }\n\n    .addr-pick-list {\n      display: flex;\n      flex-direction: column;\n      gap: 8px;\n      margin-bottom: 14px\n    }\n\n    .addr-pick-card {\n      width: 100%;\n      text-align: left;\n      padding: 13px 14px;\n      border-radius: var(--r-md);\n      border: 1.5px solid var(--line);\n      background: #fff;\n      cursor: pointer;\n      transition: border-color var(--dur-fast), background var(--dur-fast)\n    }\n\n    .addr-pick-card:hover {\n      border-color: var(--bolt-500);\n      background: var(--bolt-50)\n    }\n\n    .addr-pick-top {\n      display: flex;\n      align-items: center;\n      gap: 6px;\n      margin-bottom: 2px\n    }\n\n    .addr-pick-name {\n      font-size: 13.5px;\n      font-weight: 700\n    }\n\n    .addr-pick-badge {\n      font-size: 10px;\n      font-weight: 700;\n      color: var(--bolt-700);\n      background: var(--bolt-50);\n      padding: 2px 8px;\n      border-radius: var(--r-full)\n    }\n\n    .addr-pick-phone {\n      font-size: 12.5px;\n      color: var(--ink-soft);\n      margin-bottom: 2px\n    }\n\n    .addr-pick-line {\n      font-size: 12.5px;\n      color: var(--ink)\n    }\n\n    .addr-add-new {\n      width: 100%;\n      text-align: center;\n      padding: 12px;\n      border-radius: var(--r-md);\n      border: 1.5px dashed var(--line);\n      background: transparent;\n      color: var(--bolt-600);\n      font-weight: 700;\n      font-size: 13.5px;\n      cursor: pointer;\n      transition: background var(--dur-fast), border-color var(--dur-fast)\n    }\n\n    .addr-add-new:hover {\n      background: var(--bolt-50);\n      border-color: var(--bolt-300)\n    }\n  ";
